<script setup>
import { computed,onBeforeUnmount,onMounted,ref } from 'vue'
import { RouterLink,useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
const props=defineProps({context:{type:String,default:'site',validator:value=>['site','dashboard'].includes(value)}});const router=useRouter(),authStore=useAuthStore(),menuRef=ref(null),open=ref(false),loggingOut=ref(false);const displayName=computed(()=>{const user=authStore.user||{},full=[user.first_name,user.last_name].filter(Boolean).join(' ');return user.display_name||user.name||full||user.email||'Account'}),email=computed(()=>authStore.user?.email||''),avatarUrl=computed(()=>{const user=authStore.user||{};return user.avatar_url||user.avatar||user.profile_picture||user.photo||user.photoURL||user.picture||user.image||''}),initials=computed(()=>{const source=displayName.value.includes('@')?displayName.value.split('@')[0]:displayName.value;return source.trim().split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]?.toUpperCase()).join('')||'U'}),destination=computed(()=>props.context==='dashboard'?{to:'/',label:'Back to site'}:{to:'/dashboard',label:'Dashboard'});const closeMenu=()=>open.value=false;const click=e=>{if(open.value&&menuRef.value&&!menuRef.value.contains(e.target))closeMenu()};const escape=e=>{if(e.key==='Escape')closeMenu()};const handleLogout=async()=>{if(loggingOut.value)return;loggingOut.value=true;try{await authStore.logout();closeMenu();await router.replace('/')}finally{loggingOut.value=false}};onMounted(()=>{document.addEventListener('click',click);document.addEventListener('keydown',escape)});onBeforeUnmount(()=>{document.removeEventListener('click',click);document.removeEventListener('keydown',escape)})
</script><template><div ref="menuRef" class="account-menu"><button type="button" class="account-menu__trigger" :aria-expanded="open" aria-haspopup="menu" :aria-label="`Open account menu for ${displayName}`" @click.stop="open=!open"><img v-if="avatarUrl" :src="avatarUrl" :alt="displayName"><span v-else>{{initials}}</span></button><Transition name="account-popover"><div v-if="open" class="account-menu__popover" role="menu"><div class="account-menu__identity"><strong>{{displayName}}</strong><span v-if="email">{{email}}</span></div><div class="account-menu__divider"/><RouterLink :to="destination.to" class="account-menu__item" role="menuitem" @click="closeMenu">{{destination.label}}</RouterLink><button type="button" class="account-menu__item account-menu__logout" role="menuitem" :disabled="loggingOut" @click="handleLogout">{{loggingOut?'Logging out...':'Log out'}}</button></div></Transition></div></template><style scoped>.account-menu{position:relative;display:inline-flex}.account-menu__trigger{width:36px;height:36px;padding:0;overflow:hidden;display:grid;place-items:center;border:1px solid color-mix(in srgb,var(--color-accent) 82%,transparent);border-radius:50%;background:transparent;color:var(--color-text);font:inherit;font-size:.72rem;font-weight:750;cursor:pointer}.account-menu__trigger img{width:100%;height:100%;object-fit:cover}.account-menu__popover{position:absolute;top:calc(100% + 12px);right:0;z-index:1500;width:min(260px,calc(100vw - 28px));overflow:hidden;border:1px solid var(--color-border);border-radius:14px;background:var(--color-surface);color:var(--color-text);box-shadow:var(--shadow-elevated)}.account-menu__identity{padding:15px 16px 13px;display:grid;gap:4px}.account-menu__identity span{color:var(--color-muted);font-size:.72rem}.account-menu__divider{height:1px;background:var(--color-border)}.account-menu__item{width:100%;min-height:44px;padding:0 16px;display:flex;align-items:center;border:0;background:transparent;color:var(--color-text);font:inherit;font-size:.8rem;font-weight:600;text-align:left;text-decoration:none;cursor:pointer}.account-menu__item:hover{background:var(--color-tab-bg)}.account-menu__logout{color:#dc5f6d}.account-popover-enter-active,.account-popover-leave-active{transition:opacity .14s ease,transform .14s ease}.account-popover-enter-from,.account-popover-leave-to{opacity:0;transform:translateY(-4px)}</style>
